async def load_from_server(agent: Agent, model_server: EndpointConfig) -> Agent:
    """Load a persisted model from a server."""
    # We are going to pull the model once first, and then schedule a recurring
    # job. the benefit of this approach is that we can be sure that there
    # is a model after this function completes -> allows to do proper
    # "is alive" check on a startup server's `/status` endpoint. If the server
    # is started, we can be sure that it also already loaded (or tried to)
    # a model.
    await _update_model_from_server(model_server, agent)

    wait_time_between_pulls = model_server.kwargs.get("wait_time_between_pulls", 100)

    if wait_time_between_pulls:
        # continuously pull the model every `wait_time_between_pulls` seconds
        await _schedule_model_pulling(model_server, int(wait_time_between_pulls), agent)

    return agent


async def _load_and_set_updated_model(
    agent: Agent, model_directory: Text, fingerprint: Text
) -> None:
    """Load the persisted model into memory and set the model on the agent.

    The replacement processor is built and prepared off to the side, and only
    installed once its runtime integrations are live. Turns that start during
    the refresh therefore keep running on the previous processor instead of
    reaching a processor whose MCP connections are still being established, and
    a prepare that fails or is cancelled never touches the serving processor.

    Args:
        agent: Instance of `Agent` to update with the new model.
        model_directory: Rasa model directory.
        fingerprint: Fingerprint of the supplied model at `model_directory`.
    """
    logger.debug(
        "_load_and_set_updated_model.loading",
        message=f"Found new model with fingerprint {fingerprint}. Loading...",
    )
    replacement = agent._create_processor(model_directory)
    try:
        await _prepare_runtime_integrations(replacement)
    except BaseException:
        # Include CancelledError: a cancelled prepare must not leak the
        # connections the replacement opened before it was interrupted.
        await replacement.close_runtime_integrations()
        raise

    previous_processor = agent.processor
    # Synchronous swap: no await between here and the last assignment, so no
    # turn can observe a half-installed model.
    agent._set_loaded_model(replacement)
    agent._set_fingerprint(fingerprint)

    # Drain: close waits for in-flight MCP calls on the retired processor.
    await _close_replaced_processor(previous_processor, replacement)

    logger.debug(
        "_load_and_set_updated_model.loaded",
        message="Finished updating agent to new model.",
    )


async def _prepare_runtime_integrations(processor: MessageProcessor) -> None:
    """Prepare a processor's integrations, tagging failures as a prepare error.

    Raises:
        RuntimeIntegrationsPrepareError: If processor integration setup fails.
    """
    try:
        await processor.prepare_runtime_integrations()
    except Exception as e:
        raise RuntimeIntegrationsPrepareError(
            f"Failed to prepare runtime integrations: {e}",
            suppress_stack_trace=True,
        ) from e


async def _close_replaced_processor(
    retired: Optional[MessageProcessor],
    kept: Optional[MessageProcessor],
) -> None:
    """Close integrations on a processor that is no longer serving traffic.

    MCP close waits for in-flight tool calls on that processor so a refresh
    does not drop a connection under a live turn.
    """
    if retired is not None and retired is not kept:
        await retired.close_runtime_integrations()


async def _update_model_from_server(model_server: EndpointConfig, agent: Agent) -> None:
    """Load a zipped Rasa Core model from a URL and update the passed agent."""
    if not is_url(model_server.url):
        raise aiohttp.InvalidURL(model_server.url)
    # A missing CA bundle is a configuration error. Build the context before the
    # pull so FileNotFoundException is not treated as a transient fetch failure.
    ssl_context = model_server.create_ssl_context()

    with TempDirectoryPath(get_temp_dir_name()) as temporary_directory:
        try:
            new_fingerprint = await _pull_model_and_fingerprint(
                model_server,
                agent.fingerprint,
                temporary_directory,
                ssl_context,
            )

            if new_fingerprint:
                await _load_and_set_updated_model(
                    agent, temporary_directory, new_fingerprint
                )
            else:
                logger.debug(
                    "_update_model_from_server.no_new_model",
                    message=f"No new model found at URL {model_server.url}",
                )
        except Exception:  # skipcq: PYL-W0703
            # TODO: Make this exception more specific, possibly print different log
            # for each one.
            logger.exception(
                "_update_model_from_server.failed_to_update_model",
                message="Failed to update model. "
                "The previous model will stay loaded instead.",
            )


async def _pull_model_and_fingerprint(
    model_server: EndpointConfig,
    fingerprint: Optional[Text],
    model_directory: Text,
    ssl_context: Optional[ssl.SSLContext] = None,
) -> Optional[Text]:
    """Queries the model server.

    Args:
        model_server: Model server endpoint information.
        fingerprint: Current model fingerprint.
        model_directory: Directory where to download model to.
        ssl_context: TLS context for the pull. Built by the caller so a missing
            CA bundle fails before this function treats fetch errors as retryable.

    Returns:
        Value of the response's <ETag> header which contains the model
        hash. Returns `None` if no new model is found.
    """
    headers = {"If-None-Match": fingerprint}

    logger.debug(
        "_pull_model_and_fingerprint.requesting_model",
        message=f"Requesting model from server {model_server.url}...",
    )

    async with model_server.session() as session:
        try:
            params = model_server.combine_parameters()
            async with session.request(
                "GET",
                model_server.url,
                timeout=DEFAULT_REQUEST_TIMEOUT,
                headers=headers,
                params=params,
                ssl=ssl_context,
            ) as resp:
                if resp.status in [204, 304]:
                    logger.debug(
                        "_pull_model_and_fingerprint.no_new_model_available",
                        message="Model server returned {} status code, "
                        "indicating that no new model is available. "
                        "Current fingerprint: {}"
                        "".format(resp.status, fingerprint),
                    )
                    return None
                elif resp.status == 404:
                    logger.debug(
                        "_pull_model_and_fingerprint.model_not_found",
                        message="Model server could not find a model at the requested "
                        "endpoint '{}'. It's possible that no model has been "
                        "trained, or that the requested tag hasn't been "
                        "assigned.".format(model_server.url),
                    )
                    return None
                elif resp.status != 200:
                    logger.debug(
                        "_pull_model_and_fingerprint.failed_to_fetch_model",
                        message="Tried to fetch model from server, but server response "
                        "status code is {}. We'll retry later..."
                        "".format(resp.status),
                    )
                    return None

                model_path = _safe_model_path(
                    model_directory, resp.headers.get("filename")
                )
                with open(model_path, "wb") as file:
                    file.write(await resp.read())

                logger.debug(
                    "_pull_model_and_fingerprint.model_saved",
                    message="Saved model to '{}'".format(os.path.abspath(model_path)),
                )

                # return the new fingerprint
                return resp.headers.get("ETag")

        except aiohttp.ClientError as e:
            logger.debug(
                "_pull_model_and_fingerprint.model_server_could_not_be_reached",
                message="Tried to fetch model from server, but "
                "couldn't reach server. We'll retry later... "
                "Error: {}.".format(e),
            )
            return None


def _safe_model_path(model_directory: Text, filename: Optional[Text]) -> Text:
    """Builds the download path for a pulled model inside `model_directory`.

    The filename comes from the model server's `filename` response header, so it
    is reduced to its basename and checked against path traversal. Falls back to
    the default filename if the header is missing or unsafe.
    """
    default_filename = "model.tar.gz"
    safe_filename = Path(filename).name if filename else ""
    if safe_filename and safe_filename != filename:
        logger.warning(
            "_pull_model_and_fingerprint.unsafe_filename_stripped",
            message="Model server returned a filename with directory components. "
            "Using only its basename.",
            filename=filename,
            safe_filename=safe_filename,
        )
    try:
        return rasa.utils.io.subpath(model_directory, safe_filename or default_filename)
    except rasa.utils.io.InvalidPathException:
        logger.warning(
            "_pull_model_and_fingerprint.invalid_filename",
            message="Model server returned an invalid filename. "
            f"Falling back to '{default_filename}'.",
            filename=filename,
        )
        return rasa.utils.io.subpath(model_directory, default_filename)


async def _run_model_pulling_worker(model_server: EndpointConfig, agent: Agent) -> None:
    # noinspection PyBroadException
    try:
        await _update_model_from_server(model_server, agent)
    except CancelledError:
        logger.warning(
            "_run_model_pulling_worker.cancel_model_pull",
            message="Stopping model pulling (cancelled).",
        )
    except ClientError:
        logger.exception(
            "_run_model_pulling_worker.erro_while_fetching_model",
            message="An exception was raised while fetching a model. "
            "Continuing anyways...",
        )


async def _schedule_model_pulling(
    model_server: EndpointConfig, wait_time_between_pulls: int, agent: Agent
) -> None:
    (await jobs.scheduler()).add_job(
        _run_model_pulling_worker,
        "interval",
        seconds=wait_time_between_pulls,
        args=[model_server, agent],
        id="pull-model-from-server",
        replace_existing=True,
    )


async def load_agent(
    model_path: Optional[Text] = None,
    model_server: Optional[EndpointConfig] = None,
    remote_storage: Optional[StorageType] = None,
    endpoints: Optional[AvailableEndpoints] = None,
    sub_agents: Optional[AvailableAgents] = None,
    loop: Optional[AbstractEventLoop] = None,
    skip_rephrase_validation: bool = False,
    validate_a2a_server: bool = True,
) -> Agent:
    """Loads agent from server, remote storage or disk.

    Args:
        model_path: Path to the model if it's on disk.
        model_server: Configuration for a potential server which serves the model.
        remote_storage: Remote storage to use for loading the model.
        endpoints: Endpoint configuration.
        sub_agents: Sub-agents configuration.
        loop: Optional async loop to pass to broker creation.
        skip_rephrase_validation: If True, skip rephrase endpoint validation.
            Useful in contexts like Dialogue Understanding Tests where rephrasing
            is intentionally disabled.
        validate_a2a_server: If True, resolve the loaded engine's ``a2a_server``
            block and check it against the processor session config. ``rasa run``
            passes False: it binds A2A settings before the model loads and runs
            that check against the bound settings in
            ``bind_a2a_server_to_loaded_model``.

    Returns:
        The instantiated `Agent` or `None`.
    """
    from rasa.core.a2a_server.config_sources import (
        validate_a2a_server_for_loaded_model_or_raise,
    )
    from rasa.core.brokers.broker import EventBroker
    from rasa.core.tracker_stores.tracker_store import TrackerStore
    from rasa.validator import verify_rephrase_endpoints_consistency_or_raise

    tracker_store = None
    lock_store = None
    timer_manager = None
    generator = None
    action_endpoint = None
    http_interpreter = None
    privacy_manager = None

    if endpoints:
        broker = await EventBroker.create(endpoints.event_broker, loop=loop)
        tracker_store = TrackerStore.create(
            endpoints.tracker_store, event_broker=broker
        )
        lock_store = LockStore.create(endpoints.lock_store)
        timer_manager = create_timer_manager(endpoints.timer_store)
        generator = endpoints.nlg
        action_endpoint = endpoints.action
        model_server = endpoints.model if endpoints.model else model_server
        if endpoints.nlu:
            http_interpreter = RasaNLUHttpInterpreter(endpoints.nlu)
        from rasa.cli.project_env import resolve_project_dir
        from rasa.shared.project_structure import has_mantle_project_layout

        mantle_project = has_mantle_project_layout(resolve_project_dir())
        privacy_bootstrap = resolve_privacy_manager_bootstrap(
            endpoints, mantle_project=mantle_project
        )
        if privacy_bootstrap.should_create:
            in_memory_tracker_store = (
                tracker_store
                if isinstance(tracker_store, InMemoryTrackerStore)
                else None
            )
            privacy_manager = await BackgroundPrivacyManager.create_instance(
                endpoints=privacy_bootstrap.endpoints_for_privacy,
                event_loop=loop,
                in_memory_tracker_store=in_memory_tracker_store,
                lock_store=lock_store,
            )
            if privacy_manager.config is not None:
                track_privacy_enabled(privacy_manager.config, broker)

    agent = Agent(
        generator=generator,
        tracker_store=tracker_store,
        lock_store=lock_store,
        timer_manager=timer_manager,
        action_endpoint=action_endpoint,
        model_server=model_server,
        remote_storage=remote_storage,
        http_interpreter=http_interpreter,
        endpoints=endpoints,
        privacy_manager=privacy_manager,
    )

    try:
        if model_server is not None:
            agent = await load_from_server(agent, model_server)
            # Initialize timer manager after model is loaded
            await agent.initialize_timer_manager()
            if agent.domain is not None:
                verify_rephrase_endpoints_consistency_or_raise(
                    agent.domain,
                    endpoints,
                    skip_rephrase_validation=skip_rephrase_validation,
                )
            if validate_a2a_server:
                validate_a2a_server_for_loaded_model_or_raise(
                    agent.processor, endpoints=endpoints
                )
            return agent

        elif remote_storage is not None:
            await agent.load_model_from_remote_storage(model_path)

        elif model_path is not None and os.path.exists(model_path):
            try:
                agent.load_model(model_path)
            except ModelNotFound:
                rasa.shared.utils.io.raise_warning(
                    f"No valid model found at {model_path}!"
                )
        else:
            rasa.shared.utils.io.raise_warning(
                "No valid configuration given to load agent. "
                "Agent loaded with no model!"
            )

        await agent.prepare_runtime_integrations()

        if agent.processor and sub_agents:
            # CLI commands that accept --sub-agents all route through this entry
            # point. With the model loaded, this is the best spot to initialise
            # the sub-agents. The processor knows how: CALM v1 reads the model's
            # flows, while Mantle (empty graph, no flows_provider) is a no-op.
            await agent.processor.prepare_subagents(sub_agents)

        # Initialize timer manager after model is loaded
        await agent.initialize_timer_manager()
        # Ensure runtime rephrase settings are consistent with loaded endpoints.
        if agent.domain is not None:
            verify_rephrase_endpoints_consistency_or_raise(
                agent.domain,
                endpoints,
                skip_rephrase_validation=skip_rephrase_validation,
            )
        if validate_a2a_server:
            validate_a2a_server_for_loaded_model_or_raise(
                agent.processor, endpoints=endpoints
            )

        return agent

    except ValidationError as e:
        raise e from None
    except AgentInitializationException as e:
        if e.suppress_stack_trace:
            raise e from None
        else:
            raise e
    except LegacyFaissModelError as e:
        # Actionable retrain guidance — do not swallow into an unloaded agent,
        # which would later fail with a vague "model is not loaded" error.
        logger.error(
            "load_agent.legacy_faiss_model",
            event_info=str(e),
        )
        raise e from None
    except InvalidConfigException as e:
        # A config the model cannot run with (e.g. the orchestrator's model group
        # is gone from the live integrations file). Serving an agent with no
        # model would only surface as "No agent loaded" on the first message.
        logger.error(
            "load_agent.invalid_config",
            event_info=str(e),
        )
        raise e from None
    except RuntimeIntegrationsPrepareError as e:
        # Fail closed: do not return a ready agent without MCP / integrations.
        # Report the failing integration like the expected failures above rather
        # than dumping the connect / list_tools chain; `--debug` keeps the full
        # traceback for diagnosing which server and call site failed.
        logger.error(
            "load_agent.runtime_integrations_prepare_failed",
            event_info=str(e),
            error_type=type(e.__cause__).__name__ if e.__cause__ else None,
        )
        logger.debug(
            "load_agent.runtime_integrations_prepare_failed.debug",
            event_info=str(e),
            exc_info=True,
        )
        raise e from None
    except Exception as e:
        logger.error(
            "load_agent.could_not_load_model",
            message=f"Could not load model due to {e}.",
            exc_info=True,
        )
        return agent


def agent_must_be_ready(f: Callable[..., Any]) -> Callable[..., Any]:
    """Any Agent method decorated with this will raise if the agent is not ready."""

    @functools.wraps(f)
    def decorated(self: Agent, *args: Any, **kwargs: Any) -> Any:
        if not self.is_ready():
            raise AgentNotReady(
                "Agent needs to be prepared before usage. You need to set a "
                "processor and a tracker store."
            )
        return f(self, *args, **kwargs)

    return decorated


class Agent:
    """The Agent class provides an interface for the most important Rasa functionality.

    This includes training, handling messages, loading a dialogue model,
    getting the next action, and handling a channel.
    """

    def __init__(
        self,
        domain: Optional[Domain] = None,
        generator: Union[EndpointConfig, NaturalLanguageGenerator, None] = None,
        tracker_store: Optional[TrackerStore] = None,
        lock_store: Optional[LockStore] = None,
        timer_manager: Optional[SessionTimerManager] = None,
        action_endpoint: Optional[EndpointConfig] = None,
        fingerprint: Optional[Text] = None,
        model_server: Optional[EndpointConfig] = None,
        remote_storage: Optional[StorageType] = None,
        http_interpreter: Optional[RasaNLUHttpInterpreter] = None,
        endpoints: Optional[AvailableEndpoints] = None,
        sub_agents: Optional[AvailableAgents] = None,
        privacy_manager: Optional[BackgroundPrivacyManager] = None,
    ):
        """Initializes an `Agent`."""
        self.domain = domain
        self.processor: Optional[MessageProcessor] = None

        self.nlg = NaturalLanguageGenerator.create(generator, self.domain)
        self.tracker_store = self._create_tracker_store(tracker_store, self.domain)
        self.lock_store = self._create_lock_store(lock_store)
        self.timer_manager = self._create_timer_manager(timer_manager)
        self.action_endpoint = action_endpoint
        self.http_interpreter = http_interpreter
        self.endpoints = endpoints
        self.sub_agents = sub_agents

        self._set_fingerprint(fingerprint)
        self.model_server = model_server
        self.remote_storage = remote_storage
        self.privacy_manager = privacy_manager

    @classmethod
    def load(
        cls,
        model_path: Union[Text, Path],
        domain: Optional[Domain] = None,
        generator: Union[EndpointConfig, NaturalLanguageGenerator, None] = None,
        tracker_store: Optional[TrackerStore] = None,
        lock_store: Optional[LockStore] = None,
        timer_manager: Optional[SessionTimerManager] = None,
        action_endpoint: Optional[EndpointConfig] = None,
        fingerprint: Optional[Text] = None,
        model_server: Optional[EndpointConfig] = None,
        remote_storage: Optional[StorageType] = None,
        http_interpreter: Optional[RasaNLUHttpInterpreter] = None,
        endpoints: Optional[AvailableEndpoints] = None,
        privacy_manager: Optional[BackgroundPrivacyManager] = None,
    ) -> Agent:
        """Constructs a new agent and loads the processor and model."""
        agent = Agent(
            domain=domain,
            generator=generator,
            tracker_store=tracker_store,
            lock_store=lock_store,
            timer_manager=timer_manager,
            action_endpoint=action_endpoint,
            fingerprint=fingerprint,
            model_server=model_server,
            remote_storage=remote_storage,
            http_interpreter=http_interpreter,
            endpoints=endpoints,
            privacy_manager=privacy_manager,
        )
        agent.load_model(model_path=model_path, fingerprint=fingerprint)
        return agent

    def load_model(
        self, model_path: Union[Text, Path], fingerprint: Optional[Text] = None
    ) -> None:
        """Load the agent's model and processor given a new model path.

        This synchronous method only installs the processor. Async entry points
        must subsequently await :meth:`prepare_runtime_integrations` before the
        agent serves traffic. :func:`load_agent` and model-server refreshes
        enforce that lifecycle contract.

        Only use this on an agent that is not serving traffic yet. To refresh a
        live agent, prepare a processor from :meth:`_create_processor` first and
        install it once it is ready, as :func:`_load_and_set_updated_model` does.
        """
        self._set_loaded_model(self._create_processor(model_path))
        self._set_fingerprint(fingerprint)

    def _create_processor(self, model_path: Union[Text, Path]) -> MessageProcessor:
        """Build a processor for *model_path* without installing it on the agent."""
        return create_message_processor(
            model_path=model_path,
            tracker_store=self.tracker_store,
            lock_store=self.lock_store,
            timer_manager=self.timer_manager,
            action_endpoint=self.action_endpoint,
            generator=self.nlg,
            http_interpreter=self.http_interpreter,
            endpoints=self.endpoints,
            privacy_manager=self.privacy_manager,
        )

    @property
    def model_id(self) -> Optional[Text]:
        """Returns the model_id from processor's model_metadata."""
        return self.processor.model_metadata.model_id if self.processor else None

    @property
    def model_metadata(self) -> Optional["ModelMetadata"]:
        """Returns metadata for the currently loaded model."""
        return self.processor.model_metadata if self.processor else None

    @property
    def model_name(self) -> Optional[Text]:
        """Returns the model name from processor's model_path."""
        return self.processor.model_path.name if self.processor else None

    def is_ready(self) -> bool:
        """Check if all necessary components are instantiated to use agent."""
        return self.tracker_store is not None and self.processor is not None

    async def initialize_timer_manager(self) -> None:
        """Initialize the timer manager with callback and start it.

        This should be called after the processor is created and before
        handling messages. For Redis-based timer managers, this sets the
        callback and starts the polling loop for timer recovery.
        """
        if self.timer_manager is None or self.processor is None:
            return

        # Set the callback to processor.handle_session_timeout
        self.timer_manager.set_callback(self.processor.handle_session_timeout)

        # Start the timer manager (begins polling for Redis, no-op for in-memory)
        await self.timer_manager.start()

        logger.debug(
            "initialize_timer_manager.timer_initiailized",
            message=f"Timer manager initialized: {type(self.timer_manager).__name__}",
        )

    async def close(self) -> None:
        """Close the agent and release resources.

        This stops the timer manager and performs any necessary cleanup.
        Should be called when the agent is no longer needed.
        """
        if self.processor is not None:
            await self.processor.close_runtime_integrations()

        if self.timer_manager is not None:
            await self.timer_manager.stop()
            logger.debug(
                "initialize_timer_manager.timer_stopped",
                message="Timer manager stopped",
            )

    async def prepare_runtime_integrations(self) -> None:
        """Prepare integrations after ``load_model`` and before serving traffic.

        Raises:
            RuntimeIntegrationsPrepareError: If processor integration setup fails.
        """
        if self.processor is None:
            return
        await _prepare_runtime_integrations(self.processor)

    def stop_privacy_manager(self) -> None:
        """Stop the privacy manager's background scheduler thread, if any.

        Safe to call on agents without a privacy manager and safe to call more
        than once (``BackgroundPrivacyManager.stop`` is idempotent). Any code path
        that retires an agent (CLI test runs, server model reload/unload, builder
        agent swaps) must call this to avoid leaking the scheduler thread.
        """
        if self.privacy_manager:
            self.privacy_manager.stop()

    @agent_must_be_ready
    async def parse_message(self, message_data: Text) -> Dict[Text, Any]:
        """Handles message text and intent payload input messages.

        The return value of this function is parsed_data.

        Args:
            message_data (Text): Contain the received message in text or\
            intent payload format.

        Returns:
            The parsed message.

        Example:
                {\
                    "text": '/greet{"name":"Rasa"}',\
                    "intent": {"name": "greet", "confidence": 1.0},\
                    "intent_ranking": [{"name": "greet", "confidence": 1.0}],\
                    "entities": [{"entity": "name", "start": 6,\
                                  "end": 21, "value": "Rasa"}],\
                }

        """
        message = UserMessage(message_data)

        return await self.processor.parse_message(message)  # type: ignore[union-attr]

    @staticmethod
    def _is_running_busy_agent(tracker: DialogueStateTracker) -> bool:
        top_frame = tracker.stack.top()

        return isinstance(top_frame, AgentStackFrame) and top_frame.is_busy()

    @staticmethod
    def _has_pending_async_agent_update(tracker: DialogueStateTracker) -> bool:
        top_frame = tracker.stack.top()

        return isinstance(top_frame, AgentStackFrame) and top_frame.state in {
            AgentState.COMPLETED,
            AgentState.TERMINAL,
        }

    @staticmethod
    def _is_waiting_for_push_notification_input(
        tracker: DialogueStateTracker,
    ) -> bool:
        top_frame = tracker.stack.top()
        return (
            isinstance(top_frame, AgentStackFrame)
            and top_frame.state == AgentState.WAITING_FOR_INPUT_FROM_PUSH_NOTIFICATION
        )

    async def handle_message(
        self, message: UserMessage
    ) -> Optional[List[Dict[Text, Any]]]:
        """Handle a single message."""
        if not self.is_ready():
            logger.info(
                "handle_message.no_agent_to_handle",
                message="Ignoring message as there is no agent to handle it.",
            )
            return None

        if not message.output_channel:
            return None

        if not self.processor:
            return None

        from rasa.agents.core.cancellation import CancellationToken
        from rasa.tracing.turn import (
            TurnInputAnchor,
            TurnTriggerType,
            bind_turn_input_anchor,
        )

        token = CancellationToken()
        # Anchor the turn at ingress so turn observability measures latency from the
        # message's arrival.
        input_anchor = TurnInputAnchor(
            input_type=TurnTriggerType.TEXT, triggered_at_monotonic=time.monotonic()
        )
        try:
            with bind_turn_input_anchor(input_anchor):
                async with self.lock_store.lock(message.sender_id):
                    user_id = (
                        message.metadata.get(USER_ID) if message.metadata else None
                    )
                    tracker = await self.processor.get_tracker(
                        message.sender_id, user_id
                    )

                    if self.processor.is_duplicate_message(tracker, message):
                        logger.warning(
                            "handle_message.duplicate_message",
                            message_id=message.message_id,
                            sender_id=message.sender_id,
                        )
                        await self.processor.replay_message(tracker, message)
                        return None

                    if self._is_running_busy_agent(tracker):
                        logger.debug("handle_message.busy_agent", message=message.text)
                        stack = tracker.stack
                        stack.push(AgentStillProcessingPatternFlowStackFrame())
                        tracker.update_stack(stack)
                        await message.output_channel.notify_message_processing_started()
                        await self.processor.process_tracker(
                            message.output_channel, tracker
                        )
                        await self.processor.save_tracker(tracker)
                        await complete_channel_turn(message.output_channel, tracker)
                        return None

                    if self._is_waiting_for_push_notification_input(tracker):
                        logger.debug(
                            "handle_message.push_notification_agent_input",
                            message=message.text,
                        )
                        await message.output_channel.notify_message_processing_started()
                        await self.processor.process_tracker(
                            message.output_channel, tracker
                        )
                        await self.processor.save_tracker(tracker)
                        await complete_channel_turn(message.output_channel, tracker)
                        return None

                    if self._has_pending_async_agent_update(tracker):
                        logger.debug(
                            "handle_message.pending_async_agent_update",
                            message=message.text,
                        )
                        await message.output_channel.notify_message_processing_started()
                        await self.processor.process_tracker(
                            message.output_channel, tracker
                        )
                        await self.processor.save_tracker(tracker)
                        await complete_channel_turn(message.output_channel, tracker)
                        return None

                    self.processor.register_cancellation_token(message.sender_id, token)
                    return await self.processor.handle_message(message)
        finally:
            self.processor.unregister_cancellation_token(message.sender_id)

    async def handle_conversation(
        self,
        input_queue: ConversationQueue[InputEvent],
        output_channel: OutputChannel,
        channel_controller: Optional[ChannelController] = None,
    ) -> None:
        """Drive a voice conversation for its full duration.

        Delegates to `MessageProcessor`. No lock is held at the agent layer, but the
        per-turn lock is acquired inside the processor so it is never held for the
        duration of the call. Cancellation tokens are also registered per turn inside
        the processor's loop, aligned with how `handle_message` scopes one token per
        user message.

        Args:
            input_queue: Queue of ``InputEvent``s pushed by the voice channel.
            output_channel: Output channel for bot responses.
            channel_controller: Channel-provided controller injected into handlers so
                they can actuate channel actions (e.g. hang up).
        """
        if not self.is_ready():
            logger.warning("Ignoring conversation as there is no agent to handle it.")
            return

        processor = self.processor
        assert processor is not None
        await processor.handle_voice_conversation(
            input_queue,
            output_channel,
            input_queue.conversation_id,
            channel_controller,
        )

    def cancel_background_tasks(self, sender_id: Text) -> bool:
        """Cancel any in-flight background tasks for a conversation.

        Can be called by channels on client disconnect, by the session timer,
        or by any external system that knows the ``sender_id``.

        Returns:
            ``True`` if a token was found and signalled, ``False`` otherwise.
        """
        if self.processor:
            logger.debug(
                "cancel_background_tasks",
                message=f"Received request to cancel background tasks "
                f"for sender_id '{sender_id}'.",
            )
            return self.processor.cancel_background_tasks(sender_id)
        return False

    @agent_must_be_ready
    async def predict_next_for_sender_id(
        self, sender_id: Text
    ) -> Optional[Dict[Text, Any]]:
        """Predict the next action for a sender id."""
        return await self.processor.predict_next_for_sender_id(  # type: ignore[union-attr]
            sender_id
        )

    @agent_must_be_ready
    async def predict_next_with_tracker(
        self,
        tracker: DialogueStateTracker,
        verbosity: EventVerbosity = EventVerbosity.AFTER_RESTART,
    ) -> Optional[Dict[Text, Any]]:
        """Predicts the next action."""
        return await self.processor.predict_next_with_tracker(  # type: ignore[union-attr]
            tracker, verbosity
        )

    @agent_must_be_ready
    async def log_message(self, message: UserMessage) -> DialogueStateTracker:
        """Append a message to a dialogue - does not predict actions."""
        return await self.processor.log_message(message)  # type: ignore[union-attr]

    @agent_must_be_ready
    async def execute_action(
        self,
        sender_id: Text,
        action: Text,
        output_channel: OutputChannel,
        policy: Optional[Text],
        confidence: Optional[float],
    ) -> Optional[DialogueStateTracker]:
        """Executes an action."""
        prediction = PolicyPrediction.for_action_name(
            self.domain, action, policy, confidence or 0.0
        )
        return await self.processor.execute_action(  # type: ignore[union-attr]
            sender_id, action, output_channel, self.nlg, prediction
        )

    @agent_must_be_ready
    async def trigger_intent(
        self,
        intent_name: Text,
        entities: List[Dict[Text, Any]],
        output_channel: OutputChannel,
        tracker: DialogueStateTracker,
    ) -> None:
        """Trigger a user intent, e.g. triggered by an external event."""
        await self.processor.trigger_external_user_uttered(  # type: ignore[union-attr]
            intent_name, entities, tracker, output_channel
        )

    @agent_must_be_ready
    async def handle_text(
        self,
        text_message: Union[Text, Dict[Text, Any]],
        output_channel: Optional[OutputChannel] = None,
        sender_id: Optional[Text] = DEFAULT_SENDER_ID,
    ) -> Optional[List[Dict[Text, Any]]]:
        """Handle a single message.

        If a message preprocessor is passed, the message will be passed to that
        function first and the return value is then used as the
        input for the dialogue engine.

        The return value of this function depends on the ``output_channel``. If
        the output channel is not set, set to ``None``, or set
        to ``CollectingOutputChannel`` this function will return the messages
        the bot wants to respond.

        :Example:

            >>> from rasa.core.agent import Agent
            >>> agent = Agent.load("examples/moodbot/models")
            >>> await agent.handle_text("hello")
            [u'how can I help you?']

        """
        if isinstance(text_message, str):
            text_message = {"text": text_message}

        msg = UserMessage(text_message.get("text"), output_channel, sender_id)

        return await self.handle_message(msg)

    def _set_loaded_model(self, processor: MessageProcessor) -> None:
        """Point the agent, tracker, and NLG at a processor."""
        self.processor = processor
        self.domain = processor.domain
        self.tracker_store.domain = self.domain
        self.tracker_store.engine_version = processor.engine_version
        processor.install_privacy()
        if self.privacy_manager is not None:
            self.privacy_manager.engine_version = processor.engine_version
        # Mantle owns its slot names via the memory layer rather than a generated
        # domain, so its tracker must accept any (namespaced) slot on demand.
        self.tracker_store.use_permissive_slots = (
            getattr(processor, "engine_version", None) == MANTLE_ENGINE_VERSION
        )
        if isinstance(self.nlg, TemplatedNaturalLanguageGenerator):
            self.nlg.responses = self.domain.responses if self.domain else {}

    def _set_fingerprint(self, fingerprint: Optional[Text] = None) -> None:
        if fingerprint:
            self.fingerprint = fingerprint
        else:
            self.fingerprint = uuid.uuid4().hex

    @staticmethod
    def _create_tracker_store(
        store: Optional[TrackerStore], domain: Domain
    ) -> TrackerStore:
        if store is not None:
            store.domain = domain
            tracker_store = store
        else:
            tracker_store = InMemoryTrackerStore(domain)

        return FailSafeTrackerStore(tracker_store)

    @staticmethod
    def _create_lock_store(store: Optional[LockStore]) -> LockStore:
        if store is not None:
            return store

        return InMemoryLockStore()

    @staticmethod
    def _create_timer_manager(
        manager: Optional[SessionTimerManager],
    ) -> SessionTimerManager:
        if manager is not None:
            return manager
        return create_timer_manager()

    async def load_model_from_remote_storage(self, model_name: Text) -> None:
        """Loads an Agent from remote storage."""
        from rasa.core.persistor import get_persistor

        persistor = get_persistor(self.remote_storage)

        if persistor is not None:
            with TempDirectoryPath(get_temp_dir_name()) as temporary_directory:
                persistor.retrieve(model_name, temporary_directory)
                self.load_model(temporary_directory)

        else:
            raise RasaException(
                f"Persistor not found for remote storage: '{self.remote_storage}'."
            )
